def parse_csv_line(line: str) -> list:
    fields = []
    field = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')  # escaped quote ""
                    i += 2
                    continue
                in_quotes = False  # closing quote
            else:
                field.append(ch)
        elif ch == '"':
            in_quotes = True  # opening quote
        elif ch == ',':
            fields.append(''.join(field))  # field separator
            field = []
        else:
            field.append(ch)
        i += 1
    fields.append(''.join(field))
    return fields
